 "d": "اتفق العلماء على أن الجماع في الإحرام جناية يجب فيها الجزاء. والجمهور على أن العامد والجاهل والساهي والناسي والمكره سواء، وهو مذهب الحنفية والمالكية والحنابلة، إلا أن الحنابلة استثنوا الموطوءة كرهاً فلا فداء عليها بل القضاء فقط. وقال الشافعية: الناسي والمجنون والمغمى عليه والنائم والمكره والجاهل لقرب عهده بالإسلام لا يفسد إحرامهم بالجماع.",
