 "d": "يشترط في طواف الزيارة سوى الشروط العامة للطواف: أن يكون مسبوقاً بالإحرام، وأن يكون مسبوقاً بوقوف عرفة (فلو طاف قبل الوقوف لا يسقط به فرض الطواف إجماعاً)، والنية بأن يقصد أصل الطواف. ونية التعيين ليست شرطاً عند الجمهور (الحنفية والمالكية والشافعية) لدخوله في نية الحج. والحنابلة اشترطوا تعيين الطواف في النية. ويشترط ألا يصرفه لغيره كطلب غريم أو هرب من ظالم.",
 "ref": "الموسوعة الفقهية الكويتية، ج١٧، حج، الفقرة ٥٤",
