 "d": "استدل الجمهور على وجوبه بأمره ﷺ، كما روى ابن عباس رضي الله عنهما قال: أمر الناس أن يكون آخر عهدهم بالبيت، إلا أنه خفف عن المرأة الحائض. واستدل المالكية على أنه سنة بأنه جاز للحائض تركه دون فداء، ولو وجب لم يجز للحائض تركه.",
