 "d": "أن يكون الحاج من أهل الآفاق عند الحنفية والحنابلة، فلا يجب على المكي لأنه في وطنه. وألحق الحنفية من كان من منطقة المواقيت. وقال الحنابلة: لا يسقط إلا عمن كان منزله في الحرم فقط. وعند المالكية والشافعية يطلب في حق كل من قصد السفر من مكة، ولو كان مكياً إذا قصد سفراً تقصر فيه الصلاة.",
