 "t": "تعريف الهدي",
 "d": "الهدي لغة: ما يهدى إلى الحرم من النعم. واصطلاحاً: ما يهدى إلى الحرم من الإبل والبقر والغنم. وهو غير الأضحية التي تذكى تقرباً إلى الله في أيام النحر، وغير العقيقة المرتبطة بوقت ولادة المولود. أما الهدي ففي أيام النحر وفي الحرم.",
