 "title": "حج النفل وتكرار العمرة",
 "hukm": "حج النفل من أفضل الأعمال بحسب الموسوعة (عن هداية السالك إلى المذاهب الأربعة في المناسك)، ويقصد به الحج بعد الفريضة. وفي الدرس: المفاضلة بين حج النفل والصدقة والرباط والجهاد، وحكم الإكثار من العمرة وتكرارها في السنة، ومكان الإحرام بالعمرة لمن كان بمكة. وأحكام المناسك وفرض الحج في دروس الحج. وفي شروط حج النفل وأحكام الاستطاعة ومال الحج وغير ذلك: قيد الاستكمال.",
 "pt": 1,
 "hukmKh": ["k2"],
 "hukmRef": "الموسوعة الفقهية الكويتية، مدخل نفل، فقرة حج النفل، الصفحتان 116 و117",
 "definition": "حج النفل هو الحج المتطوع به بعد أداء الفريضة. وقد ذكرت الموسوعة هذا الموضع ضمن مدخل نفل، وفيه أن الفقهاء اختلفوا في المفاضلة بينه وبين غيره من أعمال البر. وأما العمرة فالمرجع في حكمها وأركانها إلى درس العمرة، وهنا الإكثار منها وتكرارها فقط.",
